<section class="amp-group amp-configuration-group"><h2><span>2</span>Operational amplifier</h2><label class="amp-label" for="configuration">Configuration</label><select id="configuration" aria-label="Configuration">${rt.map(e=>`<option value="${e}">${at[e]}</option>`).join("")}</select><div class="amp-device-note"><b>U1 · 741</b><span>DIP-8 · top view</span></div><p class="amp-small" id="configuration-note"></p></section>
